describe('External Links Open in New Tab', () => {
  beforeEach(() => {
    cy.visit('/external-links');
  });

  it('should open external links in a new tab', () => {
    // Verify the external link is visible and has the correct href
    cy.get('[data-testid="external-link-1"]').should('be.visible');
    cy.get('[data-testid="external-link-1"]').should('have.attr', 'href', 'https://example.com');

    // Verify the link has the target="_blank" attribute
    cy.get('[data-testid="external-link-1"]').should('have.attr', 'target', '_blank');

    // Verify the link text is correct
    cy.get('[data-testid="external-link-1"]').should('contain', 'Example Domain');

    // Verify the link opens in a new tab
    cy.get('[data-testid="external-link-1"]').click();
    cy.get('[data-testid="new-tab-indicator"]').should('be.visible');
    cy.get('[data-testid="new-tab-indicator"]').should('contain', 'New Tab');

    // Verify the original page is still visible
    cy.url().should('include', '/external-links');
  });

  it('should handle multiple external links and open all in new tabs', () => {
    // Verify multiple external links are present
    cy.get('[data-testid="external-link-2"]').should('be.visible');
    cy.get('[data-testid="external-link-3"]').should('be.visible');

    // Verify all links have the target="_blank" attribute
    cy.get('[data-testid="external-link-2"]').should('have.attr', 'target', '_blank');
    cy.get('[data-testid="external-link-3"]').should('have.attr', 'target', '_blank');

    // Verify all links open in new tabs
    cy.get('[data-testid="external-link-2"]').click();
    cy.get('[data-testid="new-tab-indicator"]').should('be.visible');
    cy.get('[data-testid="external-link-2"]').should('have.attr', 'target', '_blank');

    cy.get('[data-testid="external-link-3"]').click();
    cy.get('[data-testid="new-tab-indicator"]').should('be.visible');
    cy.get('[data-testid="external-link-3"]').should('have.attr', 'target', '_blank');

    // Verify the original page is still visible
    cy.url().should('include', '/external-links');
  });
});
